module power (
    input signed [7:0] in_0,
    input signed [3:0] in_1,
    output signed [15:0] out
);
    parameter signed [4:0] WIDTH = 4'd8;
    parameter signed [4:0] HEIGHT = 4'd16;

    wire [4:0] x_start = 5'd0;
    wire [4:0] x_end = (WIDTH == 5'd0) ? 5'd0 : (WIDTH - 5'd1);
    wire [4:0] y_start = 5'd0;
    wire [4:0] y_end = (HEIGHT == 5'd0) ? 5'd0 : (HEIGHT - 5'd1);

    wire signed [63:0] initial_l = 64'd0;

    genvar i, j;
    generate
        for (i = 0; i < 5; i = i + 1) begin : gen_x
            for (j = 0; j < 5; j = j + 1) begin : gen_y
                localparam [4:0] x_curr = x_start + i;
                localparam [4:0] y_curr = y_start + j;

                wire signed [63:0] x_shift = x_curr >>> 1;
                wire signed [63:0] y_shift = y_curr >>> 1;

                wire signed [127:0] product = in_0 * in_1;
                wire signed [63:0] product_signed = {{35{64{product[127]} }} , product[127:1]};

                wire signed [63:0] x_times_y = x_shift * y_shift;
                wire signed [63:0] x_times_y_ext = $signed({{35{35{x_times_y[63]} }} , x_times_y[63:1]});
                wire signed [63:0] x_times_y_ext_signed = x_times_y_ext;
                wire signed [127:0] sum = product_signed + x_times_y_ext_signed;

                wire [63:0] sum_shifted = sum >>> 1;
                wire [63:0] sum_shifted_ext = $signed({{35{63{sum_shifted[63]} }} , sum_shifted[63:1]});

                if (sum_shifted[0] == 1'b0)
                    initial_l[i*j + 1] = sum_shifted_ext[63];
            end
        end
    endgenerate

    assign out = initial_l;

endmodule

