  function parse_number;
    input [15:0] binary;
    integer [3:0] tens;
    integer [3:0] units;
    integer [3:0] total;
    integer i;
    begin
      parse_number.out = 1'b0;
      for (i = 0; i < 4; i = i + 1) begin
        tens = (i >= 2) ? 4'd1 : 4'd0;
        if (tens * 4'd10 >= (i + 1)) begin
          total = (i + 1) - tens;
          if (total >= 4'd1) begin
            parse_number.out = (total - 4'd1) >>> 1;
